import { describe, expect, it } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

/**
 * Landing copy, checked against the anti-AI-slop standard the email generator
 * is already held to.
 *
 * These files are regenerated by the visual builder, and copy regressions are
 * invisible in a diff review — a reinstated "45 minutes" reads like a detail,
 * not like a claim about a named competitor's product that nobody measured.
 */
const DIR = "src/components/landing";
const FILES = readdirSync(DIR).filter((f) => f.endsWith(".tsx"));
const ALL = FILES.map((f) => ({ file: f, text: readFileSync(join(DIR, f), "utf8") }));

/** Copy only: strip imports, styles, class names and code comments. */
const prose = (text: string) =>
  text
    .replace(/\/\*[\s\S]*?\*\//g, " ")
    .replace(/^\s*\/\/.*$/gm, " ")
    .replace(/className=(?:"[^"]*"|\{[^}]*\})/g, " ")
    .replace(/style=\{\{[\s\S]*?\}\}/g, " ")
    .replace(/^import .*$/gm, " ");

describe("no unsourced time claims", () => {
  // Every one of these was on the page at once, and they disagreed: the
  // workflow was advertised as taking 2 minutes, 20 minutes and 60 seconds.
  const BANNED = [
    "2+ hours",
    "45 minutes",
    "60 seconds",
    "30 seconds",
    "under 20 minutes",
    "under 2 minutes",
    "< 2 min",
  ];

  for (const claim of BANNED) {
    it(`does not promise "${claim}"`, () => {
      const hits = ALL.filter((f) => prose(f.text).toLowerCase().includes(claim.toLowerCase()));
      expect(hits.map((h) => h.file)).toEqual([]);
    });
  }

  it("says how long it takes without inventing a figure", () => {
    const stat = readFileSync(join(DIR, "BigStatSection.tsx"), "utf8");
    expect(stat).toContain("A few");
    expect(stat).toContain("minutes");
  });
});

describe("the schema.org description matches the page", () => {
  const SEO = readFileSync("src/components/seo/StructuredData.tsx", "utf8");

  it("does not advertise a duration the page no longer claims", () => {
    // Otherwise the search result says "under 2 minutes" for a page that does not.
    expect(SEO).not.toContain("under 2 minutes");
  });
});

describe("negation is not the default rhetorical move", () => {
  it("keeps stacked negations out of a single sentence", () => {
    // "no boolean search, no list building, no manual scoring" — three in a row.
    for (const { file, text } of ALL) {
      const sentences = prose(text).split(/(?<=[.!?])\s+/);
      for (const s of sentences) {
        const negations = (s.match(/\bno\b|\bwithout\b|\bnever\b/gi) ?? []).length;
        expect(negations, `${file}: ${s.trim().slice(0, 90)}`).toBeLessThan(3);
      }
    }
  });
});

describe("'actually' is not a tic", () => {
  it("is used at most once across the landing page", () => {
    // It hedges: if a claim needs "actually" to land, the claim is the problem.
    // One earned use survives — "Questions we actually get asked".
    //
    // BlogStrip is excluded: its strings are the titles of published articles,
    // so they are records of what was written rather than copy to edit here.
    const uses = ALL.filter(({ file }) => file !== "BlogStrip.tsx").flatMap(({ file, text }) =>
      (prose(text).match(/\bactually\b/gi) ?? []).map(() => file),
    );
    expect(uses.length, `used in: ${uses.join(", ")}`).toBeLessThanOrEqual(1);
  });
});

describe("the AI SDR grid speaks in one voice", () => {
  it("makes the agent the subject of every card", () => {
    const src = readFileSync(join(DIR, "AISdrSection.tsx"), "utf8");
    const titles = [...src.matchAll(/title:\s*"([^"]+)"/g)].map((m) => m[1]);
    expect(titles.length).toBeGreaterThan(3);
    for (const t of titles) {
      // Imperatives addressed to the reader ("Know who's ready", "Never miss")
      // sat next to agent-subject cards ("Finds the leads for you").
      expect(t, t).not.toMatch(/^(Know|Never|See|Get|Stay|Make)\b/);
    }
  });
});

/**
 * Voice: the company speaks as "we" everywhere except the founder note, which
 * speaks as "I". A first-person promise in marketing copy ("I will build your
 * campaign") reads as one person's availability rather than something the
 * product does, and it is the first thing to slip when copy is regenerated.
 *
 * Not policed: FAQ questions and the exit-modal dismiss button, where the
 * VISITOR is speaking, and simulated inbox previews, where a prospect is.
 */
describe("company voice outside the founder note", () => {
  const FIRST_PERSON = /(?<![A-Za-z])(I|I'll|I'm|I've|my|me|myself)(?![A-Za-z'])/;

  const declarative = ["HeroSection.tsx", "FinalCTA.tsx", "ProblemSection.tsx", "AISdrSection.tsx"];

  for (const file of declarative) {
    it(`${file} speaks as the company`, () => {
      const text = prose(readFileSync(join(DIR, file), "utf8"))
        // Drop JSX/attribute noise so only sentence-like content is judged.
        .split("\n")
        .filter((l) => !/(import |=>|https?:|aria-|key=|const |function )/.test(l))
        .join("\n");
      const hit = text.split("\n").find((l) => FIRST_PERSON.test(l) && /[a-z]{4,}\s+[a-z]{3,}/.test(l));
      expect(hit ?? "", `first person in ${file}: ${hit?.trim().slice(0, 90)}`).toBe("");
    });
  }

  it("leaves the founder note in the first person, where it belongs", () => {
    // The credibility of that section is that a person is talking. Anyone
    // "fixing" it to company voice is breaking it.
    const founder = readFileSync(join(DIR, "FounderNoteSection.tsx"), "utf8");
    expect(FIRST_PERSON.test(founder)).toBe(true);
    expect(founder).toContain("I was paying $500/month");
  });
});

/**
 * The free plan is 100 SEARCHES at up to 25 results each, not 100 prospects.
 *
 * fetch-external-leads charges `remainingCredits - 1` per search and only when
 * `chargesPerSearch = userPlan === 'free'`, against
 * PLAN_SEARCH_LIMITS.free.monthlySearchCredits = 100 with maxResultsPerSearch
 * 25. Calling it "100 verified prospects" understated the offer by up to 25x.
 */
describe("the free plan is described as what it is", () => {
  const PRICING = readFileSync("src/components/Pricing.tsx", "utf8");
  const LIMITS = readFileSync("supabase/functions/_shared/plan-limits.ts", "utf8");

  it("still matches the source of truth it is quoting", () => {
    expect(LIMITS).toContain("free: { monthlySearchCredits: 100");
    expect(LIMITS).toContain("maxResultsPerSearch: 25 }");
  });

  it("does not sell searches as a prospect count", () => {
    for (const { file, text } of ALL) {
      expect(prose(text), file).not.toContain("100 verified prospects");
      expect(prose(text), file).not.toContain("100 free leads");
    }
  });

  it("says searches where it means searches", () => {
    expect(prose(readFileSync(join(DIR, "HeroSection.tsx"), "utf8"))).toContain("100 free lead searches");
    expect(prose(readFileSync(join(DIR, "FinalCTA.tsx"), "utf8"))).toContain("100 free lead searches");
  });

  it("does not label a row of search credits as verified prospects", () => {
    // The row read "Monthly verified prospects" with free: "100 searches" and
    // paid values that are search credits, so it misdescribed every column.
    expect(PRICING).not.toContain('name: "Monthly verified prospects"');
    expect(PRICING).toContain('name: "Monthly lead searches"');
  });
});

/**
 * The blog makes the same promises the homepage does, to the same reader, and
 * search engines and LLMs read it alongside llms-txt. It carried "under 2
 * minutes" in six calls to action after the homepage had stopped claiming a
 * duration, so the two surfaces disagreed about the product.
 */
describe("blog claims match the rest of the site", () => {
  const BLOG = readFileSync("src/data/blog-content.ts", "utf8");

  it("does not promise a duration the homepage no longer claims", () => {
    expect(BLOG).not.toContain("under 2 minutes");
  });

  it("does not assert invented durations about a competitor's product", () => {
    // "2+ hours per campaign" and "30–45 minutes" to write a boolean query
    // were precise claims about Apollo that nobody measured.
    expect(BLOG).not.toContain("2+ hours");
    expect(BLOG).not.toContain("30–45 minutes");
  });

  it("leaves ordinary writing advice alone", () => {
    // Sanding every number out of craft prose is the over-correction the
    // anti-slop standard warns about. These are reader-time estimates in
    // advice, not product promises.
    expect(BLOG).toContain("say yes in 2 minutes");
    expect(BLOG).toContain("20 minutes of staring at a blank page");
  });
});

/**
 * The hero has to let someone start.
 *
 * Both of its buttons needed a human on the other end: book a campaign-setup
 * call, or open the demo. The trust line two rows below promised "100 free lead
 * searches" and there was nothing on the screen to click for them, so a visitor
 * who was ready to start had to go looking for the door.
 */
describe("the hero lets someone start", () => {
  const HERO = readFileSync(join(DIR, "HeroSection.tsx"), "utf8");

  it("offers the free plan it promises two rows below", () => {
    expect(HERO).toContain("Start free");
    expect(HERO).toContain('href="/auth"');
  });

  it("keeps the campaign-setup call, below it rather than instead of it", () => {
    // It is the real differentiator, so it stays. Compared against the handler
    // on the button, not the import at the top of the file.
    expect(HERO).toContain("openCampaignSetupBooking");
    expect(HERO.indexOf("Start free")).toBeLessThan(HERO.indexOf('openCampaignSetupBooking("hero_book_setup"'));
  });

  it("renders nothing from the session, which would break hydration", () => {
    // The hero is prerendered to static HTML and hydrated over. `signedIn` is
    // false during the server pass, so branching on it in markup mismatches the
    // first client paint. It is read inside the click handler instead, which is
    // what the booking CTA beside it already did.
    expect(HERO).toContain('navigate(signedIn ? "/dashboard" : "/auth")');
    expect(HERO).not.toMatch(/\{signedIn \?[^}]*\}\s*</);
  });
});

/**
 * Two house rules from the writing standard, checked rather than remembered:
 * no em dashes in shipped prose, and none of the banned vocabulary.
 *
 * Deliberately NOT policed here: the duration claim. "A few minutes" is the
 * honest answer to something nobody measured, and the banned-claims list at the
 * top of this file is what keeps a fabricated number from coming back in its
 * place.
 */
describe("no AI tells in shipped landing copy", () => {
  /** Line-wise, so an offender can be named by file and line. */
  const proseLines = (text: string) =>
    text.split("\n").filter((l) => {
      const t = l.trim();
      return !t.startsWith("//") && !t.startsWith("*") && !t.startsWith("/*") && !t.startsWith("{/*") && !l.includes("{/*");
    });

  const SURFACES = [...ALL, { file: "Index.tsx", text: readFileSync("src/pages/Index.tsx", "utf8") }];

  it("uses no em dashes outside simulated app chrome", () => {
    // What survives is a separator inside mock product UI ("OutReign — AI SDR
    // · Activity Feed"), where a dash names a pane rather than punctuating a
    // sentence.
    const offenders: string[] = [];
    for (const { file, text } of SURFACES) {
      proseLines(text).forEach((l, i) => {
        if (!l.includes("—")) return;
        if (/OutReign —|AI Draft —/.test(l)) return;
        offenders.push(`${file}:${i + 1}: ${l.trim().slice(0, 70)}`);
      });
    }
    expect(offenders).toEqual([]);
  });

  it("uses none of the banned vocabulary", () => {
    const banned =
      /\b(leverage|utilize|seamless|robust|holistic|unlock|elevate|supercharge|empower|cutting-edge|game-chang\w*|delve|tapestry|realm|synergy|testament|myriad|take it to the next level|move the needle)\b/i;
    const offenders: string[] = [];
    for (const { file, text } of SURFACES) {
      proseLines(text).forEach((l, i) => {
        const m = l.match(banned);
        if (m) offenders.push(`${file}:${i + 1}: ${m[0]}`);
      });
    }
    expect(offenders).toEqual([]);
  });

  it("asserts what things are without first saying what they are not", () => {
    // Negative parallelism: "It's not X, it's Y", "Not just X, but Y". The
    // single most common tell, and it hides in many shapes.
    const offenders: string[] = [];
    for (const { file, text } of SURFACES) {
      proseLines(text).forEach((l, i) => {
        if (/(it'?s not [a-z ]{3,30}, it'?s|not just [a-z ]{3,30}, (but )?[a-z]|we don'?t just)/i.test(l)) {
          offenders.push(`${file}:${i + 1}`);
        }
      });
    }
    expect(offenders).toEqual([]);
  });

  it("the sample email does not read as machine-written", () => {
    // It is the one artifact on the page showing what the product writes, and
    // an em dash straight after the greeting is the most recognisable tell
    // there is — on the page whose whole job is answering that objection.
    const steps = readFileSync(join(DIR, "HowItWorks.tsx"), "utf8");
    expect(steps).toContain("Hey Jordan, saw Northline");
    expect(steps).not.toContain("Hey Jordan —");
  });
});
